// between the pishtaq edge and the chamfer)
for (const sideOff of [-14, 14]) {
  for (const lvl of [0, BODY_H / 2]) {
    const n = archedPanel(4.4, BODY_H / 2 - 1.2, 1.0, 1.5, 8, { band: false });
    n.position.set(sd.x, PLINTH_TOP + lvl + 0.6, sd.z);
    n.rotation.y = sd.ry;
    n.translateX(sideOff);
    n.translateZ(0.03);
    taj.add(n);
  }
}
